const input = $input.first().json;
const body = input.body || {};
const after = String(body.after || '').trim();
const before = String(body.before || '').trim();
const hasAfter = Boolean(after);
const hasBefore = Boolean(before);
if (hasAfter && !/^\d{4}\/\d{2}\/\d{2}$/.test(after)) throw new Error('after must use YYYY/MM/DD format');
if (hasBefore && !/^\d{4}\/\d{2}\/\d{2}$/.test(before)) throw new Error('before must use YYYY/MM/DD format');
const custom = body.queries;
let bases;
if (custom !== undefined) {
  if (!Array.isArray(custom) || custom.length === 0) throw new Error('queries must be a non-empty array when provided');
  const cleaned = custom.map((query) => String(query || '').trim());
  if (cleaned.some((query) => !query)) throw new Error('queries may not contain empty values');
  bases = cleaned.map((query, index) => ({ source_query: `Custom query ${index + 1}`, query }));
} else {
  if (!hasAfter || !hasBefore) throw new Error('Body must contain after and before in YYYY/MM/DD format');
  bases = [
    { source_query: 'Application Updates', query: 'label:"Job Search/Application Updates"' },
    { source_query: 'Interviews & Offers', query: 'label:"Job Search/Interviews & Offers"' },
    { source_query: 'Job Alerts application events', query: 'label:"Job Search/Job Alerts" (subject:"successfully submitted" OR subject:"has closed" OR subject:"application")' },
    { source_query: 'Sent application messages', query: 'in:sent (application OR applying OR resume OR CV OR "job opening" OR position)' },
  ];
}
const dateParts = [];
if (hasAfter) dateParts.push(`after:${after}`);
if (hasBefore) dateParts.push(`before:${before}`);
return bases.map((entry) => ({ json: { source_query: entry.source_query, query: [entry.query, ...dateParts].join(' ') } }));

const items = $input.all();
const byId = new Map();
const clean = (value) => String(value ?? '').replace(/[\u034F\u200B\u200C\u200D\u00AD\uFEFF]/g, '').replace(/\s+/g, ' ').trim();
for (let i = 0; i < items.length; i += 1) {
  const msg = items[i].json || {};
  const messageId = clean(msg.id || msg.messageId);
  if (!messageId) continue;
  let source = clean(msg.source_query);
  try { source = clean($('Queries').itemMatching(i).json.source_query) || source; } catch {}
  const rawDate = msg.internalDate ? Number(msg.internalDate) : msg.date;
  const parsedDate = new Date(rawDate);
  const normalized = {
    message_id: messageId,
    thread_id: clean(msg.threadId || msg.thread_id),
    sources: source ? [source] : [],
    date: Number.isNaN(parsedDate.getTime()) ? '' : parsedDate.toISOString(),
    from: clean(msg.From || msg.from),
    to: clean(msg.To || msg.to),
    subject: clean(msg.Subject || msg.subject),
    snippet: clean(msg.snippet),
  };
  if (byId.has(messageId)) {
    const existing = byId.get(messageId);
    for (const s of normalized.sources) if (!existing.sources.includes(s)) existing.sources.push(s);
    if (!existing.snippet && normalized.snippet) existing.snippet = normalized.snippet;
  } else {
    byId.set(messageId, normalized);
  }
}
return Array.from(byId.values()).map((json) => ({ json }));
